            x, y = int(p[0]), int(p[1])
        elif isinstance(p, dict):
            if "position" in p and isinstance(p["position"], (list, tuple)) and len(p["position"]) >= 2:
                x, y = int(p["position"][0]), int(p["position"][1])
            elif "x" in p and "y" in p:
                x, y = int(p["x"]), int(p["y"])
            else:
                continue
        else:
            continue
        if 0 <= x < w and 0 <= y < h:
            obstacles.add((x, y))

    resources = []
    for r in (observation.get("resources", []) or []):
        if isinstance(r, (list, tuple)) and len(r) >= 2:
            x, y = int(r[0]), int(r[1])
        elif isinstance(r, dict):
            if "position" in r and isinstance(r["position"], (list, tuple)) and len(r["position"]) >= 2:
                x, y = int(r["position"][0]), int(r["position"][1])
            elif "x" in r and "y" in r:
                x, y = int(r["x"]), int(r["y"])
            else:
                continue
        else:
            continue
        if 0 <= x < w and 0 <= y < h:
            resources.append((x, y))

    if not resources:
        return [0, 0]

    def clamp(a, lo, hi):
        return lo if a < lo else hi if a > hi else a

    dirs = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)]
    best = None
    best_val = -10**18

    for dx, dy in dirs:
